import{_ as s,o as e,c as t,a2 as p}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"节南山","description":"","frontmatter":{"title":"节南山","date":"2026-11-08T00:00:00.000Z","seq":31,"categories":["美文","诗经"],"collection":"《诗经 · 小雅》","tags":["诗经","先秦"],"poem":true,"author":"佚名","source_book":"诗经"},"headers":[],"relativePath":"blogs/诗经·小雅/节南山.md","filePath":"blogs/诗经·小雅/节南山.md"}'),o={name:"blogs/诗经·小雅/节南山.md"};function c(l,a,n,r,_,m){return e(),t("div",null,[...a[0]||(a[0]=[p('<h1 id="节南山" tabindex="-1">节南山 <a class="header-anchor" href="#节南山" aria-label="Permalink to &quot;节南山&quot;">​</a></h1><p class="poem-meta">先秦 · 佚名　·　节南山之什</p><div class="poem"><p class="poem-stanza">节彼南山，维石岩岩。赫赫师尹，民具尔瞻。忧心如惔，不敢戏谈。国既卒斩，何用不监！</p><p class="poem-stanza">节彼南山，有实其猗。赫赫师尹，不平谓何。天方荐瘥，丧乱弘多。民言无嘉，惨莫惩嗟。</p><p class="poem-stanza">尹氏大师，维周之氐；秉国之钧，四方是维。天子是毗，俾民不迷。不吊昊天，不宜空我师。</p><p class="poem-stanza">弗躬弗亲，庶民弗信。弗问弗仕，勿罔君子。式夷式已，无小人殆。琐琐姻亚，则无膴仕。</p><p class="poem-stanza">昊天不佣，降此鞠訩。昊天不惠，降此大戾。君子如届，俾民心阕。君子如夷，恶怒是违。</p><p class="poem-stanza">不吊昊天，乱靡有定。式月斯生，俾民不宁。忧心如酲，谁秉国成？不自为政，卒劳百姓。</p><p class="poem-stanza">驾彼四牡，四牡项领。我瞻四方，蹙蹙靡所骋。</p><p class="poem-stanza">方茂尔恶，相尔矛矣。既夷既怿，如相酬矣。</p><p class="poem-stanza">昊天不平，我王不宁。不惩其心，覆怨其正。</p><p class="poem-stanza">家父作诵，以究王訩。式讹尔心，以畜万邦。</p></div>',3)])])}const u=s(o,[["render",c]]);export{d as __pageData,u as default};
